add(1, { definitions: { x: I }, $ref: '#/definitions/x', type: 'boolean' }, 'ref passes, sibling type:boolean would fail -> 0');
add(1, { $ref: '#/definitions/x', definitions: { x: true }, type: 'string' }, 'ref->true, sibling type:string would fail -> 0');
add(1, { definitions: { x: I }, allOf: [{ $ref: '#/definitions/x', maximum: 0 }] }, 'sibling maximum ignored -> 0');
add(1, { definitions: { x: S }, allOf: [{ $ref: '#/definitions/x', type: 'boolean' }] }, 'both would fail; only $ref counted -> 1 (NOT 2)');
add(1, { definitions: { x: { $ref: '#/definitions/y', type: 'string' }, y: true }, $ref: '#/definitions/x' }, 'sibling ignored one level down the ref chain -> 0');
add(1, { definitions: { x: { $ref: '#/definitions/y', type: 'integer' }, y: S }, $ref: '#/definitions/x' }, 'chain: inner $ref applies, its sibling ignored -> 1');
add(1, { definitions: { x: true }, allOf: [{ $schema: D2020, $ref: '#/definitions/x', type: 'string', maximum: 0 }] }, '2020-12 subschema STILL ignores $ref siblings -> 0');
add(1, { definitions: { x: true }, allOf: [{ $schema: D2020, type: 'string', maximum: 0, $ref: '#/definitions/x' }] }, 'same with $ref written last -> 0 (key order irrelevant)');
add(1, { definitions: { x: I }, allOf: [{ $schema: D2019, $ref: '#/definitions/x', maximum: 0 }] }, '2019-09 subschema ignores $ref siblings -> 0');
add({ a: 1 }, { definitions: { x: true }, allOf: [{ $schema: D2019, $ref: '#/definitions/x', dependentRequired: { a: ['b'] } }] }, '2019-09: dependentRequired sibling of $ref ignored -> 0');
add(1, { definitions: { x: I }, allOf: [{ $schema: D6, $ref: '#/definitions/x', maximum: 0 }] }, 'draft6 subschema ignores $ref siblings -> 0');
add(1, { definitions: { x: S }, allOf: [{ $schema: D4, $ref: '#/definitions/x', maximum: 0 }] }, 'draft4 subschema: both would fail, only $ref -> 1');

/* ---------- B. local JSON pointers ---------- */
