add(1, { definitions: { x: true }, $ref: '#/definitions/x' }, 'pointer to boolean true schema -> 0');
add(1, { definitions: { x: false }, $ref: '#/definitions/x' }, 'pointer to boolean false schema -> 1');
add(1, { definitions: { x: {} }, $ref: '#/definitions/x' }, 'pointer to {} -> 0');
add(1, { allOf: [S, I], $ref: '#/allOf/0' }, 'pointer INTO array #/allOf/0 (allOf sibling ignored) -> 1');
add(1, { allOf: [S, I], $ref: '#/allOf/1' }, 'pointer #/allOf/1 -> integer passes -> 0');
add(1, { definitions: { a: { allOf: [S] } }, $ref: '#/definitions/a/allOf/0' }, 'pointer through definitions then array -> 1');
add(1, { x: [S], $ref: '#/x/0' }, 'pointer into array under an UNKNOWN keyword -> 1');
add(1, { x: [[S]], $ref: '#/x/0/0' }, 'pointer into nested arrays -> 1');
add(1, { allOf: [{ allOf: [S] }], $ref: '#/allOf/0/allOf/0' }, 'deep array pointer -> 1');
add(1, { definitions: { x: { definitions: { y: S } } }, $ref: '#/definitions/x/definitions/y' }, 'nested definitions pointer -> 1');
add(1, { $defs: { x: S }, $ref: '#/$defs/x' }, '$defs pointer works in draft7 (plain pointer walk) -> 1');
add(1, { definitions: { x: S }, $ref: '#/definitions' }, 'pointer to the definitions MAP: validated as schema, unknown keys ignored -> 0');
add(1, { properties: { a: S }, $ref: '#/properties' }, 'pointer to the properties MAP -> 0');
add({ a: 1 }, { properties: { a: S }, allOf: [{ $ref: '#/properties/a' }] }, 'ref to #/properties/a applies to WHOLE instance: 1 (properties) + 1 (allOf) -> 2');
add(1, { '': S, $ref: '#/' }, 'pointer "#/" = key "" present -> 1');
