add(1, { definitions: { 'é': S }, $ref: '#/definitions/%C3%A9' }, 'UTF-8 percent decoding -> 1');
add(1, { definitions: { 'é': S }, $ref: '#/definitions/é' }, 'raw non-ASCII key -> 1');

/* ---------- D. array indices use Python int() ---------- */
const AR = { allOf: [S, I] };
add(1, { ...AR, $ref: '#/allOf/5' }, 'array index out of range -> PointerToNowhere exception');
add(1, { ...AR, $ref: '#/allOf/x' }, 'non-numeric segment into an array -> ValueError exception (NOT PointerToNowhere)');
add(1, { ...AR, $ref: '#/allOf/-1' }, 'NEGATIVE index: -1 = last element (integer) -> 0');
