add(1, { ...AR, $ref: '#/allOf/%201%09' }, 'whitespace-padded " 1\\t" accepted by int() -> 0');
add(1, { ...AR, $ref: '#/allOf/１' }, 'FULLWIDTH DIGIT ONE accepted by int() -> index 1 -> 0');
add(1, { ...AR, $ref: '#/allOf/1_0' }, 'underscore separator: int("1_0")==10 -> out of range -> exception');
add(1, { allOf: [S, S, S, S, S, S, S, S, S, S, I], $ref: '#/allOf/1_0' }, 'int("1_0")==10 -> 11th element (integer) -> 0');
add(1, { ...AR, $ref: '#/allOf/1.0' }, '"1.0" rejected by int() -> ValueError exception');
add(1, { x: 'abc', $ref: '#/x/1' }, 'strings are Sequences: "#/x/1" indexes the string -> then non-schema -> exception');
add(1, { x: 'abc', $ref: '#/x/9' }, 'string index out of range -> PointerToNowhere exception');
add(1, { x: 'abc', $ref: '#/x/z' }, 'non-numeric index into string -> ValueError exception');

/* ---------- E. pointer target is not an object/boolean ---------- */
add(1, { definitions: { x: 'hello' }, $ref: '#/definitions/x' }, 'target string -> AttributeError exception');
add(1, { definitions: { x: 5 }, $ref: '#/definitions/x' }, 'target int -> TypeError exception');
add(1, { definitions: { x: null }, $ref: '#/definitions/x' }, 'target null -> TypeError exception');
